const money = value => `₹${Math.abs(Number(value || 0)).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:0})}`;
const signedMoney = value => `${Number(value)>=0?'+':'−'}${money(value)}`;
const signedPct = value => `${Number(value)>=0?'+':'−'}${Math.abs(Number(value || 0)).toFixed(2)}%`;
async function api(path, options={}) {
  const headers = {'Content-Type':'application/json',...(options.headers||{})};
  if(authToken) headers.Authorization=`Bearer ${authToken}`;
  const response = await fetch(path,{...options,headers});
  const payload = await response.json().catch(()=>({error:'Unexpected server response'}));
  if(!response.ok) throw new Error(payload.error || `Request failed (${response.status})`);
  return payload;
}

function ingestDashboard(data) {
  liveSummary=data.summary; liveUniverse=data.universe; currentUser=data.user; activeRisk=data.settings.risk_profile;
  document.querySelector('.account strong').textContent=data.user.name;
  document.querySelector('.account small').textContent=`${activeRisk[0].toUpperCase()+activeRisk.slice(1)} risk`;
  document.querySelector('.avatar').textContent=data.user.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
  holdings=data.holdings.map(h=>[h.symbol,h.name,h.quantity,money(h.average_price),money(h.ltp),money(h.current_value),signedMoney(h.pnl),signedPct(h.pnl_pct),h.weight]);
  history=data.trades.map(t=>({time:new Date(t.created_at).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}),symbol:t.symbol,name:t.name,action:t.action,qty:t.quantity,price:Number(t.price).toLocaleString('en-IN',{minimumFractionDigits:2}),value:Number(t.current_value).toLocaleString('en-IN',{minimumFractionDigits:2}),pnl:signedMoney(t.pnl),pct:signedPct(t.pnl_pct),up:t.pnl>=0,reason:t.reasoning}));
  trades=history.slice(0,3);
  hotStocks=data.hot_stocks.map(s=>({symbol:s.symbol,name:s.name,price:money(s.price),change:signedPct(s.change_pct),confidence:Math.round(s.confidence),note:s.reasoning}));
}

async function refreshData() { const data=await api('/api/dashboard'); ingestDashboard(data); return data; }
let marketTimer=null;
function applyMarketUpdate(data){const nodes=document.querySelectorAll('.ticker-item');data.indices.slice(0,nodes.length).forEach((item,i)=>{const n=nodes[i];n.querySelector('strong').textContent=Number(item.price).toLocaleString('en-IN',{minimumFractionDigits:2});const em=n.querySelector('em');em.className=item.change_pct>=0?'up':'down';em.innerHTML=`${icon(item.change_pct>=0?'trending-up':'trending-down')}${Math.abs(item.change_pct).toFixed(2)}%`;});const delay=document.querySelector('.data-delay');if(delay)delay.textContent=`Simulated · updated ${new Date(data.updated_at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}`;if(window.lucide)lucide.createIcons();}
async function updateMarket(){if(!authToken)return;try{applyMarketUpdate(await api('/api/market/update'))}catch(_){} }
function startMarketUpdater(){if(marketTimer)clearInterval(marketTimer);updateMarket();marketTimer=setInterval(updateMarket,60000);}

function metric(label,value,foot,iconName,primary='') { return `<article class="metric ${primary}"><div class="metric-label"><span>${label}</span>${icon(iconName)}</div><strong class="metric-value">${value}</strong><div class="metric-foot">${foot}</div></article>`; }
function tradeRows(list, withReason=true) {
  return list.map((t,i)=>`<tr><td class="mono">${t.time}</td><td><div class="stock-cell">${logo(t.symbol)}<div><strong>${t.symbol}</strong><small>NSE</small></div></div></td><td><span class="action-pill ${t.action.toLowerCase()}">${t.action}</span></td><td class="mono">${t.qty}</td><td class="mono">₹${t.price}</td><td class="mono">₹${t.value}</td><td class="mono ${t.up?'up':'down'}"><strong>${t.pnl}</strong><br><small>${t.pct}</small></td>${withReason?`<td><button class="reason-btn" data-reason="${i}">${icon('message-square-text')} View thesis</button></td>`:''}</tr>${withReason?`<tr class="reason-row" data-reason-row="${i}"><td colspan="8"><div class="reason-content"><b>AI trade thesis · </b>${t.reason}</div></td></tr>`:''}`).join('');
}
