function chartsPage(){const symbols=[...new Set([...holdings.map(h=>h[0]),...hotStocks.map(s=>s.symbol)])];return `<div class="page-intro chart-page-intro"><div><h2>Advanced stock chart</h2><p>Multi-timeframe price action and technical indicators</p></div><div class="analysis-controls"><select id="chartSymbol">${symbols.map(s=>`<option>${s}</option>`).join('')}</select><button class="secondary-btn" id="reloadChart">${icon('refresh-cw')} Refresh</button></div></div><section class="panel trading-chart-shell"><div class="chart-toolbar"><div class="timeframe-tabs">${['1m','5m','15m','1H','1D'].map(t=>`<button data-timeframe="${t}" class="${t==='5m'?'active':''}">${t}</button>`).join('')}</div><div class="indicator-tabs"><span>Indicators</span>${[['ema20','EMA 20'],['ema50','EMA 50'],['bollinger','BB'],['volume','Volume'],['rsi14','RSI']].map(([id,label])=>`<button data-indicator="${id}" class="${activeIndicators.has(id)?'active':''}">${label}</button>`).join('')}</div></div><div id="chartCanvas" class="chart-canvas"><div class="analysis-loading">${icon('loader-circle')} Loading candles…</div></div></section><div class="analysis-disclaimer chart-disclaimer">${icon('info')} TradingView-style workflow with original rendering. Simulated candles until a licensed market feed is connected.</div>`;}

function linePath(values,x,y,offset=0){return values.map((value,i)=>`${i?'L':'M'}${x(i+offset).toFixed(1)},${y(value).toFixed(1)}`).join(' ')}
function renderStockChart(data){currentChartData=data;const count=100,start=Math.max(0,data.candles.length-count),candles=data.candles.slice(start),ind=data.indicators,w=900,h=360,priceBottom=270,volumeTop=282,volumeBottom=345,x=i=>12+i*((w-54)/candles.length),allPrices=candles.flatMap(c=>[c.high,c.low]);if(activeIndicators.has('ema20'))allPrices.push(...ind.ema20.slice(start));if(activeIndicators.has('ema50'))allPrices.push(...ind.ema50.slice(start));if(activeIndicators.has('bollinger'))allPrices.push(...ind.bollinger.upper.slice(start),...ind.bollinger.lower.slice(start));const min=Math.min(...allPrices),max=Math.max(...allPrices),y=v=>15+(max-v)/(max-min||1)*(priceBottom-25),maxVol=Math.max(...candles.map(c=>c.volume)),vy=v=>volumeBottom-v/maxVol*(volumeBottom-volumeTop),last=candles[candles.length-1],up=data.change>=0,bbUpper=ind.bollinger.upper.slice(start),bbLower=ind.bollinger.lower.slice(start),bbPath=activeIndicators.has('bollinger')?`<path class="bb-fill" d="${linePath(bbUpper,x,y)} ${bbLower.map((v,i)=>`L${x(bbLower.length-1-i).toFixed(1)},${y(bbLower[bbLower.length-1-i]).toFixed(1)}`).join(' ')} Z"/><path class="bb-line" d="${linePath(bbUpper,x,y)}"/><path class="bb-line" d="${linePath(bbLower,x,y)}"/>`:'';const svg=`<svg id="mainStockChart" class="main-stock-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><g class="stock-grid"><path d="M0 60H900M0 130H900M0 200H900M0 270H900M0 345H900"/></g>${bbPath}${activeIndicators.has('ema20')?`<path class="ema-line ema20" d="${linePath(ind.ema20.slice(start),x,y)}"/>`:''}${activeIndicators.has('ema50')?`<path class="ema-line ema50" d="${linePath(ind.ema50.slice(start),x,y)}"/>`:''}${candles.map((c,i)=>{const rise=c.close>=c.open,color=rise?'#138b61':'#d64d4d',xx=x(i),yo=y(c.open),yc=y(c.close);return `<line x1="${xx}" y1="${y(c.high)}" x2="${xx}" y2="${y(c.low)}" stroke="${color}"/><rect x="${xx-2.7}" y="${Math.min(yo,yc)}" width="5.4" height="${Math.max(1.2,Math.abs(yo-yc))}" fill="${color}" rx=".6"/>${activeIndicators.has('volume')?`<rect x="${xx-2.7}" y="${vy(c.volume)}" width="5.4" height="${volumeBottom-vy(c.volume)}" fill="${color}" opacity=".35"/>`:''}`}).join('')}<line class="last-price-line" x1="0" y1="${y(last.close)}" x2="866" y2="${y(last.close)}"/><rect class="last-price-label ${up?'positive':'negative'}" x="866" y="${y(last.close)-9}" width="34" height="18" rx="3"/><text x="883" y="${y(last.close)+3}" text-anchor="middle" class="price-label-text">${last.close.toFixed(0)}</text><line id="crosshairX" class="chart-crosshair" x1="0" y1="0" x2="0" y2="345" visibility="hidden"/><line id="crosshairY" class="chart-crosshair" x1="0" y1="0" x2="866" y2="0" visibility="hidden"/></svg>`;const rsiValues=ind.rsi14.slice(start),rsiSvg=activeIndicators.has('rsi14')?`<div class="rsi-panel"><span>RSI 14 <b>${rsiValues[rsiValues.length-1].toFixed(1)}</b></span><svg viewBox="0 0 900 110" preserveAspectRatio="none"><path class="rsi-zone" d="M0 25H900M0 80H900"/><path class="rsi-line" d="${linePath(rsiValues,x,v=>95-v*.85)}"/></svg></div>`:'';document.getElementById('chartCanvas').innerHTML=`<div class="chart-quote-row"><div><strong>${data.symbol}</strong><span>${data.exchange} · ${data.timeframe}</span></div><div class="ohlc"><span>O <b>${last.open.toFixed(2)}</b></span><span>H <b>${last.high.toFixed(2)}</b></span><span>L <b>${last.low.toFixed(2)}</b></span><span>C <b>${last.close.toFixed(2)}</b></span></div><div class="chart-last"><strong>${data.price.toFixed(2)}</strong><span class="${up?'up':'down'}">${up?'+':''}${data.change.toFixed(2)} (${up?'+':''}${data.change_pct.toFixed(2)}%)</span></div></div><div class="chart-hover" id="chartHover">Hover chart for candle details</div>${svg}${rsiSvg}<div class="chart-foot"><span>${new Date(candles[0].time).toLocaleString('en-IN')}</span><span>${data.data_mode.toUpperCase()} DATA · ${candles.length} BARS</span><span>${new Date(last.time).toLocaleString('en-IN')}</span></div>`;wireChartHover(candles,x,y);}

function backtestPage(){const end=new Date(),start=new Date(end);start.setFullYear(end.getFullYear()-1);const iso=d=>d.toISOString().slice(0,10),symbols=[...new Set([...holdings.map(h=>h[0]),...hotStocks.map(s=>s.symbol)])];return `<div class="page-intro"><div><h2>Historical model validation</h2><p>Test NSE strategies on a chronological holdout before risking paper capital</p></div></div><section class="panel backtest-controls"><label>Stock<select id="backtestSymbol">${symbols.map(s=>`<option>${s}</option>`).join('')}</select></label><label>Strategy<select id="backtestStrategy"><option value="ensemble">AI ensemble</option><option value="momentum">Momentum</option><option value="mean_reversion">Mean reversion</option><option value="breakout">Volume breakout</option></select></label><label>From<input type="date" id="backtestStart" value="${iso(start)}"></label><label>To<input type="date" id="backtestEnd" value="${iso(end)}"></label><label>Capital<input type="number" id="backtestCapital" value="1000000" min="10000" step="10000"></label><button class="primary-btn" id="runBacktest">${icon('play')} Run backtest</button></section><div class="analysis-disclaimer">${icon('shield-alert')} Validation includes next-open execution, estimated 12 bps costs, and a chronological 70/30 train-test split.</div><div id="backtestBody"><section class="panel backtest-empty"><div>${icon('flask-conical')}</div><h3>Ready to test a hypothesis</h3><p>Choose a stock, strategy, and period. Results distinguish training performance from unseen holdout data.</p></section></div>`}

function universePage(){const counts=liveUniverse?.counts||{NSE:0,BSE:0,total:0};return `<div class="page-intro"><div><h2>All active listed equities</h2><p>Searchable official security master for NSE and BSE</p></div><span class="summary-pill">Master coverage <b>${Number(counts.total).toLocaleString('en-IN')}</b></span></div><section class="universe-stats"><article><span>Total active securities</span><strong>${Number(counts.total).toLocaleString('en-IN')}</strong><small>Combined exchange records</small></article><article><span>NSE equity master</span><strong>${Number(counts.NSE).toLocaleString('en-IN')}</strong><small>NSE EQUITY_L</small></article><article><span>BSE active equity</span><strong>${Number(counts.BSE).toLocaleString('en-IN')}</strong><small>BSE public API</small></article><article><span>Strategy control</span><strong>Algorithmic</strong><small>No manual strategy selection</small></article></section><div class="universe-toolbar"><label class="field">${icon('search')}<input id="securitySearch" placeholder="Search symbol, company, ISIN or BSE code…"></label><div class="exchange-tabs"><button class="active" data-exchange="ALL">All</button><button data-exchange="NSE">NSE</button><button data-exchange="BSE">BSE</button></div></div><div class="analysis-disclaimer">${icon('database')} Inclusion in the master does not mean a live quote or trade is available. The algorithm must pass data freshness, liquidity, risk and broker-eligibility checks.</div><section class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Exchange</th><th>Symbol / code</th><th>Company</th><th>Series / group</th><th>ISIN</th><th>Status</th></tr></thead><tbody id="securityRows"><tr><td colspan="6" class="empty-state">Loading exchange master…</td></tr></tbody></table></div><div class="universe-pagination"><span id="securityCount">—</span><div><button class="secondary-btn" id="securityPrev" disabled>${icon('chevron-left')} Previous</button><button class="secondary-btn" id="securityNext">Next ${icon('chevron-right')}</button></div></div></section>`}

function renderSecurities(data){
  document.getElementById('securityRows').innerHTML=data.items.map(s=>`<tr><td><span class="exchange-pill ${s.exchange.toLowerCase()}">${s.exchange}</span></td><td><strong>${s.symbol}</strong><small class="security-code">${s.exchange==='BSE'?s.code:s.series}</small></td><td>${s.name}</td><td class="mono">${s.series||'—'}</td><td class="mono">${s.isin||'—'}</td><td><span class="active-security"><i></i>${s.status}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">No matching securities.</td></tr>';
  const from=data.total?data.offset+1:0,to=Math.min(data.total,data.offset+data.limit);
  document.getElementById('securityCount').textContent=`Showing ${from.toLocaleString('en-IN')}–${to.toLocaleString('en-IN')} of ${data.total.toLocaleString('en-IN')}`;
  document.getElementById('securityPrev').disabled=data.offset===0;
  document.getElementById('securityNext').disabled=data.offset+data.limit>=data.total;
}

function renderBacktest(r){const m=r.out_of_sample,pf=m.profit_factor==null?'∞':m.profit_factor.toFixed(2),metric=(label,value,sub,cls='')=>`<article class="backtest-metric"><span>${label}</span><strong class="${cls}">${value}</strong><small>${sub}</small></article>`;document.getElementById('backtestBody').innerHTML=`<section class="backtest-report-head"><div><span class="data-source ${r.data_mode}">${r.data_mode} data</span><h3>${r.symbol} · ${r.strategy.replace('_',' ')}</h3><p>${r.period.start} → ${r.period.end} · ${r.period.sessions} sessions · ${r.source}</p></div><div class="verdict ${r.verdict}"><span>Holdout verdict</span><strong>${r.verdict.toUpperCase()}</strong></div></section><section class="backtest-metrics">${metric('Net return',`${m.return_pct>=0?'+':''}${m.return_pct.toFixed(2)}%`,`${signedMoney(m.net_pnl)} on unseen data`,m.return_pct>=0?'up':'down')}${metric('Directional accuracy',`${m.directional_accuracy.toFixed(1)}%`,`${m.wins} wins · ${m.losses} losses`)}${metric('Profit factor',pf,'Gross profit ÷ gross loss')}${metric('Maximum drawdown',`${m.max_drawdown_pct.toFixed(2)}%`,'Peak-to-trough','down')}${metric('Sharpe ratio',m.sharpe.toFixed(2),'Risk-adjusted return')}${metric('Benchmark',`${r.benchmark_return_pct>=0?'+':''}${r.benchmark_return_pct.toFixed(2)}%`,'Buy-and-hold holdout',r.benchmark_return_pct>=0?'up':'down')}</section><section class="backtest-comparison"><article class="panel"><div class="panel-head"><div><h3>Training vs unseen data</h3><p>Large deterioration is a warning for overfitting</p></div></div><div class="sample-bars"><div><span>Training return</span><b class="${r.in_sample.return_pct>=0?'up':'down'}">${signedPct(r.in_sample.return_pct)}</b><i><em style="width:${Math.min(100,Math.abs(r.in_sample.return_pct)*3+5)}%"></em></i></div><div><span>Holdout return</span><b class="${m.return_pct>=0?'up':'down'}">${signedPct(m.return_pct)}</b><i><em style="width:${Math.min(100,Math.abs(m.return_pct)*3+5)}%"></em></i></div><div><span>Holdout win rate</span><b>${m.win_rate.toFixed(1)}%</b><i><em style="width:${m.win_rate}%"></em></i></div></div></article><article class="panel method-card"><h3>Test integrity</h3><ul><li>${icon('check')} Signals use completed candles only</li><li>${icon('check')} Orders execute on the next open</li><li>${icon('check')} Costs and slippage estimate included</li><li>${icon('check')} Final 30% never used for fitting</li></ul></article></section><section class="panel table-panel"><div class="panel-head"><div><h3>Recent holdout trades</h3><p>Auditable executions used in the report</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Signal date</th><th>Trade date</th><th>Side</th><th>Entry</th><th>Exit</th><th>Net P&amp;L</th><th>Return</th></tr></thead><tbody>${m.recent_trades.map(t=>`<tr><td>${t.signal_date}</td><td>${t.trade_date}</td><td><span class="action-pill ${t.side==='LONG'?'buy':'sell'}">${t.side}</span></td><td class="mono">${money(t.entry)}</td><td class="mono">${money(t.exit)}</td><td class="mono ${t.pnl>=0?'up':'down'}">${signedMoney(t.pnl)}</td><td class="mono ${t.return_pct>=0?'up':'down'}">${signedPct(t.return_pct)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty-state">No signals in the holdout period.</td></tr>'}</tbody></table></div></section><p class="backtest-warning">${icon('triangle-alert')} ${r.warning}</p>`;if(window.lucide)lucide.createIcons()}
function wireChartHover(candles,x,y){const svg=document.getElementById('mainStockChart');if(!svg)return;svg.addEventListener('mousemove',e=>{const rect=svg.getBoundingClientRect(),px=(e.clientX-rect.left)/rect.width*900,idx=Math.max(0,Math.min(candles.length-1,Math.round((px-12)/((900-54)/candles.length)))),c=candles[idx],xx=x(idx),yy=y(c.close),cx=document.getElementById('crosshairX'),cy=document.getElementById('crosshairY');cx.setAttribute('x1',xx);cx.setAttribute('x2',xx);cx.setAttribute('visibility','visible');cy.setAttribute('y1',yy);cy.setAttribute('y2',yy);cy.setAttribute('visibility','visible');document.getElementById('chartHover').textContent=`${new Date(c.time).toLocaleString('en-IN')} · O ${c.open.toFixed(2)}  H ${c.high.toFixed(2)}  L ${c.low.toFixed(2)}  C ${c.close.toFixed(2)}  Vol ${c.volume.toLocaleString('en-IN')}`;});svg.addEventListener('mouseleave',()=>{document.getElementById('crosshairX').setAttribute('visibility','hidden');document.getElementById('crosshairY').setAttribute('visibility','hidden')});}

function sentimentPage(){const symbols=[...new Set([...holdings.map(h=>h[0]),...hotStocks.map(s=>s.symbol)])];return `<div class="page-intro"><div><h2>Market sentiment radar</h2><p>News tone confirmed against price, volume, and overall market breadth</p></div><div class="analysis-controls"><select id="sentimentSymbol">${symbols.map(s=>`<option>${s}</option>`).join('')}</select><button class="primary-btn" id="refreshSentiment">${icon('refresh-cw')} Refresh pulse</button></div></div><div class="analysis-disclaimer">${icon('radio')} Simulated headlines until a licensed news provider is connected. Scores show evidence, not certainty.</div><div id="sentimentBody"><section class="panel analysis-loading">${icon('loader-circle')} Reading the market pulse…</section></div>`;}

function renderSentiment(data){const s=data.selected,m=data.market_mood,labelClass=s.label==='bullish'?'up':s.label==='bearish'?'down':'';const componentNames={news:'News tone',price_action:'Price action',volume:'Volume confirmation',market_breadth:'Market breadth'};document.getElementById('sentimentBody').innerHTML=`<section class="sentiment-hero"><article class="sentiment-score ${s.label}"><span>${s.symbol} sentiment</span><strong>${s.score>0?'+':''}${s.score}</strong><b>${s.label.toUpperCase()}</b><small>${s.confidence}% confidence · ${s.coverage.articles} stories</small></article><article class="panel mood-card"><div><span>Market mood</span><strong>${m.label.toUpperCase()}</strong><small>${m.score>0?'+':''}${m.score}/100 composite</small></div><div class="mood-distribution"><span class="mood-up" style="width:${m.bullish/(m.bullish+m.neutral+m.bearish)*100}%"></span><span class="mood-flat" style="width:${m.neutral/(m.bullish+m.neutral+m.bearish)*100}%"></span><span class="mood-down" style="width:${m.bearish/(m.bullish+m.neutral+m.bearish)*100}%"></span></div><div class="mood-legend"><span>${m.bullish} bullish</span><span>${m.neutral} neutral</span><span>${m.bearish} bearish</span></div></article><article class="panel sentiment-summary"><span>AI summary</span><p>${s.summary}</p><small>Updated ${new Date(s.updated_at).toLocaleTimeString('en-IN')} · ${s.data_mode} data</small></article></section><section class="sentiment-layout"><article class="panel"><div class="panel-head"><div><h3>Signal composition</h3><p>Why the score moved</p></div></div><div class="sentiment-components">${Object.entries(s.components).map(([key,value])=>`<div><span>${componentNames[key]}</span><div class="sentiment-track"><i class="${value>=0?'positive':'negative'}" style="width:${Math.abs(value)}%;${value<0?'margin-left:'+(100-Math.abs(value))+'%;':''}"></i></div><b class="${value>=0?'up':'down'}">${value>0?'+':''}${value}</b></div>`).join('')}</div></article><article class="panel"><div class="panel-head"><div><h3>Headline evidence</h3><p>Source-level sentiment</p></div></div><div class="headline-list">${s.headlines.map(h=>`<div><i class="${h.score>0?'up':h.score<0?'down':''}">${h.score>0?'+':''}${h.score}</i><p>${h.headline}<small>${h.source}</small></p></div>`).join('')}</div></article></section><div class="section-head sentiment-leader-head"><div><h2>Sentiment leaders</h2><p>Strongest positive narratives in the monitored universe</p></div></div><section class="sentiment-leaders">${data.leaders.slice(0,5).map(x=>`<article><div>${logo(x.symbol)}<span><strong>${x.symbol}</strong><small>${x.label}</small></span></div><b class="${x.score>=0?'up':'down'}">${x.score>0?'+':''}${x.score}</b></article>`).join('')}</section>`;if(window.lucide)lucide.createIcons();}

function candleChart(candles=[]) { if(!candles.length)return'';const slice=candles.slice(-60),w=720,h=210,min=Math.min(...slice.map(c=>c.low)),max=Math.max(...slice.map(c=>c.high)),x=i=>10+i*(700/slice.length),y=v=>10+(max-v)/(max-min||1)*180;return `<svg class="candle-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><path class="chart-grid" d="M0 40H720M0 100H720M0 160H720"/>${slice.map((c,i)=>{const up=c.close>=c.open,color=up?'#138b61':'#d64d4d',xx=x(i),yo=y(c.open),yc=y(c.close);return `<line x1="${xx}" y1="${y(c.high)}" x2="${xx}" y2="${y(c.low)}" stroke="${color}" stroke-width="1"/><rect x="${xx-3}" y="${Math.min(yo,yc)}" width="6" height="${Math.max(1,Math.abs(yo-yc))}" rx="1" fill="${color}"/>`}).join('')}</svg>`;}

function renderAnalysis(a,g={}) { const ms=a.market_structure,plan=a.trade_plan,fvg=a.fvg?.[a.fvg.length-1],provider=a.model.narrative_provider==='local'?'Local analysis model':`${a.model.narrative_provider} · ${a.model.narrative_model}`; document.getElementById('analysisBody').innerHTML=`<section class="analysis-signal-grid"><article class="signal-card dark"><span>Model bias</span><strong class="${a.bias==='bullish'?'up':a.bias==='bearish'?'down':''}">${a.bias.toUpperCase()}</strong><small>${a.confidence}% confluence confidence</small></article><article class="signal-card"><span>Entry / CMP</span><strong>${money(plan.entry)}</strong><small>${plan.direction} paper setup</small></article><article class="signal-card"><span>SL → TP</span><strong>${money(plan.sl)} → ${money(plan.tp)}</strong><small>R:R 1:${plan.risk_reward.toFixed(1)}</small></article><article class="signal-card"><span>Liquidity</span><strong>${money(a.liquidity.ssl)} / ${money(a.liquidity.bsl)}</strong><small>SSL / BSL</small></article></section><section class="analysis-layout"><article class="panel chart-analysis"><div class="panel-head"><div><h3>${a.symbol} structure map</h3><p>LTF 1m · HTF 15m · updated ${new Date(a.updated_at).toLocaleTimeString('en-IN')}</p></div><span class="status-badge"><span></span>Every minute</span></div>${candleChart(a.candles)}<div class="structure-levels"><span>SR support <b>${money(a.support_resistance.support)}</b></span><span>POI <b>${money(a.poi.low)}–${money(a.poi.high)}</b></span><span>SR resistance <b>${money(a.support_resistance.resistance)}</b></span></div></article><article class="panel structure-panel"><div class="panel-head"><div><h3>Structure engine</h3><p>Detected conditions</p></div></div><div class="structure-list"><div><span>MS</span><b>${ms.state}</b></div><div><span>BOS</span><b>${ms.bos}</b></div><div><span>MSS</span><b class="${ms.mss?'up':''}">${ms.mss?'Detected':'No'}</b></div><div><span>CHOCH</span><b>${ms.choch?'Detected':'No'}</b></div><div><span>EQH / EQL</span><b>${ms.eqh?'EQH ':''}${ms.eql?'EQL':'—'}</b></div><div><span>OB</span><b>${a.order_block.type} ${money(a.order_block.low)}–${money(a.order_block.high)}</b></div><div><span>FVG / IMB</span><b>${fvg?`${fvg.type} ${money(fvg.low)}–${money(fvg.high)}`:'None active'}</b></div><div><span>PIP / LOT</span><b>₹${plan.tick_size.toFixed(2)} / ${plan.lot_size}</b></div></div></article></section><section class="panel model-narrative"><div class="model-badge">${icon('brain-circuit')} ${provider}</div><h3>AI desk interpretation</h3><p>${a.narrative}</p></section><div class="section-head glossary-head"><div><h2>Trading language, decoded</h2><p>The engine’s terms in plain English</p></div></div><section class="glossary-grid">${Object.entries(g).map(([term,desc])=>`<article><strong>${term}</strong><p>${desc}</p></article>`).join('')}</section>`; if(window.lucide)lucide.createIcons(); }

function strategiesPage() { const categories=['All',...new Set(strategies.map(s=>s[6]))]; return `<div class="page-intro"><div><h2>Strategy library</h2><p>Payoff-aware playbooks for Indian cash, futures, and options research</p></div><span class="summary-pill">Documented playbooks <b>${strategies.length}</b></span></div><div class="analysis-disclaimer">${icon('shield-alert')} Strategy knowledge does not imply profitability. Derivatives require margin, expiry, liquidity, settlement, tax, and tail-risk controls.</div><div class="strategy-filter-bar">${categories.map((c,i)=>`<button class="${i===0?'active':''}" data-strategy-filter="${c}">${c}<span>${c==='All'?strategies.length:strategies.filter(s=>s[6]===c).length}</span></button>`).join('')}</div><section class="strategy-grid">${strategies.map(s=>`<article class="strategy-card" data-strategy-category="${s[6]}"><div class="strategy-card-top"><span class="strategy-number">PLAYBOOK ${s[0]}</span><span class="risk-chip risk-${s[7].toLowerCase().replace(/\s+/g,'-')}">${s[7]} risk</span></div>${icon(s[2])}<small class="strategy-category">${s[6]}</small><h3>${s[1]}</h3><p>${s[3]}</p><div class="strategy-tags">${s[4].map(t=>`<span>${t}</span>`).join('')}</div><div class="ai-note">${icon('sparkles')}<span><b>Risk note:</b> ${s[5]}</span></div></article>`).join('')}</section>`; }

function settingsPage() { const opt=(id,title,desc,risk)=>`<div class="risk-option ${activeRisk===id?'active':''}" data-risk="${id}"><span class="radio"></span><div><strong>${title}</strong><small>${desc}</small></div><em>${risk} / trade</em></div>`; return `<div class="page-intro"><div><h2>Workspace settings</h2><p>Manage agent risk, capital, model connections, and paper-trading preferences</p></div></div><section class="settings-grid"><article class="panel settings-card"><h3>Risk profile</h3><p>Controls position sizing, maximum drawdown, and stop-loss behaviour.</p><div class="risk-options">${opt('conservative','Conservative','Prioritise capital protection','1%')}${opt('balanced','Balanced','Measured growth and risk','2%')}${opt('aggressive','Aggressive','Higher volatility tolerance','3.5%')}</div></article><article class="panel settings-card danger-zone"><h3>Paper capital</h3><p>Reset your simulation and begin again with a clean portfolio.</p><div class="capital-box"><span>Current starting capital</span><strong>${money(liveSummary?.starting_capital||1000000)}</strong></div><button class="danger-btn" id="resetCapital">${icon('rotate-ccw')} Reset paper portfolio</button></article><article class="panel settings-card gateway-card"><div class="gateway-heading"><div><h3>AI gateway</h3><p>Controlled bridge between the trading engine and external model APIs.</p></div><span class="status-badge"><span></span>Protected</span></div><div id="gatewayStatus" class="gateway-loading">${icon('loader-circle')} Checking provider connections…</div></article></section>`; }

function render(view='dashboard') {
  const pages = {dashboard,positions:positionsPage,history:historyPage,analysis:analysisPage,charts:chartsPage,universe:universePage,backtest:backtestPage,sentiment:sentimentPage,strategies:strategiesPage,settings:settingsPage};
  content.innerHTML = pages[view]();
  document.getElementById('pageEyebrow').textContent = titles[view][0];
  document.getElementById('pageTitle').textContent = titles[view][1];
  document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  if(view==='dashboard'&&liveUniverse){const copy=document.querySelector('.agent-panel > p');if(copy)copy.textContent=`The master covers ${liveUniverse.counts.total.toLocaleString('en-IN')} active NSE/BSE securities. The engine chooses each strategy from market regime and current portfolio position.`}
  if(window.lucide) lucide.createIcons();
  wirePage(view);
  window.scrollTo({top:0,behavior:'smooth'});
}

function wirePage(view) {
  document.querySelectorAll('[data-reason]').forEach(btn=>btn.addEventListener('click',()=>document.querySelector(`[data-reason-row="${btn.dataset.reason}"]`).classList.toggle('open')));
  document.querySelectorAll('.run-agent').forEach(b=>b.addEventListener('click',runAgent));
  document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>render(b.dataset.go)));
  if(view==='history') {
    const update=()=>{ const q=document.getElementById('tradeSearch').value.toUpperCase(); const a=document.getElementById('actionFilter').value; document.getElementById('historyBody').innerHTML=tradeRows(history.filter(t=>t.symbol.includes(q)&&(a==='ALL'||t.action===a)),false); };
    document.getElementById('tradeSearch').addEventListener('input',update); document.getElementById('actionFilter').addEventListener('change',update);
  }
  if(view==='analysis') {
    const load=async(force=false)=>{const symbol=document.getElementById('analysisSymbol').value;const button=document.getElementById('runAnalysis');button.disabled=true;try{const [analysis,terms]=await Promise.all([api(force?'/api/analysis/run':`/api/analysis?symbol=${encodeURIComponent(symbol)}`,force?{method:'POST',body:JSON.stringify({symbol})}:{method:'GET'}),api('/api/glossary')]);renderAnalysis(analysis,terms)}catch(err){document.getElementById('analysisBody').innerHTML=`<section class="panel empty-state">${err.message}</section>`}finally{button.disabled=false}};
    document.getElementById('runAnalysis').addEventListener('click',()=>load(true));document.getElementById('analysisSymbol').addEventListener('change',()=>load(false));load(false);
  }
  if(view==='charts'){
    let timeframe='5m';const load=async()=>{const canvas=document.getElementById('chartCanvas');canvas.innerHTML=`<div class="analysis-loading">${icon('loader-circle')} Loading candles…</div>`;if(window.lucide)lucide.createIcons();try{renderStockChart(await api(`/api/chart?symbol=${encodeURIComponent(document.getElementById('chartSymbol').value)}&timeframe=${encodeURIComponent(timeframe)}`))}catch(err){canvas.innerHTML=`<div class="empty-state">${err.message}</div>`}};document.querySelectorAll('[data-timeframe]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-timeframe]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');timeframe=btn.dataset.timeframe;load()}));document.querySelectorAll('[data-indicator]').forEach(btn=>btn.addEventListener('click',()=>{const id=btn.dataset.indicator;activeIndicators.has(id)?activeIndicators.delete(id):activeIndicators.add(id);btn.classList.toggle('active',activeIndicators.has(id));if(currentChartData)renderStockChart(currentChartData)}));document.getElementById('chartSymbol').addEventListener('change',load);document.getElementById('reloadChart').addEventListener('click',load);load();
  }
  if(view==='backtest'){
    const backtestStrategy=document.getElementById('backtestStrategy');backtestStrategy.innerHTML='<option value="ensemble">Algorithmic auto-select</option>';backtestStrategy.disabled=true;
    document.getElementById('runBacktest').addEventListener('click',async()=>{const button=document.getElementById('runBacktest');button.disabled=true;button.innerHTML=`${icon('loader-circle')} Testing…`;if(window.lucide)lucide.createIcons();try{renderBacktest(await api('/api/backtest',{method:'POST',body:JSON.stringify({symbol:document.getElementById('backtestSymbol').value,strategy:document.getElementById('backtestStrategy').value,start:document.getElementById('backtestStart').value,end:document.getElementById('backtestEnd').value,capital:Number(document.getElementById('backtestCapital').value)})}))}catch(err){document.getElementById('backtestBody').innerHTML=`<section class="panel empty-state">${err.message}</section>`}finally{button.disabled=false;button.innerHTML=`${icon('play')} Run backtest`;if(window.lucide)lucide.createIcons()}});
  }
  if(view==='universe'){
    let exchange='ALL',offset=0,query='';const load=async()=>{try{const data=await api(`/api/securities?exchange=${exchange}&query=${encodeURIComponent(query)}&limit=50&offset=${offset}`);renderSecurities(data)}catch(err){document.getElementById('securityRows').innerHTML=`<tr><td colspan="6" class="empty-state">${err.message}</td></tr>`}};let searchTimer;document.getElementById('securitySearch').addEventListener('input',event=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{query=event.target.value;offset=0;load()},250)});document.querySelectorAll('[data-exchange]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-exchange]').forEach(item=>item.classList.remove('active'));button.classList.add('active');exchange=button.dataset.exchange;offset=0;load()}));document.getElementById('securityPrev').addEventListener('click',()=>{offset=Math.max(0,offset-50);load()});document.getElementById('securityNext').addEventListener('click',()=>{offset+=50;load()});load();
  }
  if(view==='strategies') {
    document.querySelectorAll('[data-strategy-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-strategy-filter]').forEach(item=>item.classList.remove('active'));button.classList.add('active');document.querySelectorAll('[data-strategy-category]').forEach(card=>card.hidden=button.dataset.strategyFilter!=='All'&&card.dataset.strategyCategory!==button.dataset.strategyFilter)}));
  }
  if(view==='sentiment'){
    const load=async()=>{const button=document.getElementById('refreshSentiment');button.disabled=true;try{renderSentiment(await api(`/api/sentiment?symbol=${encodeURIComponent(document.getElementById('sentimentSymbol').value)}`))}catch(err){document.getElementById('sentimentBody').innerHTML=`<section class="panel empty-state">${err.message}</section>`}finally{button.disabled=false}};document.getElementById('refreshSentiment').addEventListener('click',load);document.getElementById('sentimentSymbol').addEventListener('change',load);load();
  }
  if(view==='settings') {
    document.querySelectorAll('.risk-option').forEach(o=>o.addEventListener('click',async()=>{try{await api('/api/settings',{method:'PUT',body:JSON.stringify({risk_profile:o.dataset.risk})});activeRisk=o.dataset.risk;document.querySelectorAll('.risk-option').forEach(x=>x.classList.remove('active'));o.classList.add('active');document.querySelector('.account small').textContent=`${activeRisk[0].toUpperCase()+activeRisk.slice(1)} risk`;}catch(err){showToast('Could not save settings',err.message)}}));
    document.getElementById('resetCapital').addEventListener('click',()=>toggleModal(true));
    api('/api/ai/gateway/status').then(renderGatewayStatus).catch(err=>document.getElementById('gatewayStatus').textContent=err.message);
  }
}

function renderGatewayStatus(data){const active=data.active,stats=data.last_24h,controls=data.controls;document.getElementById('gatewayStatus').innerHTML=`<div class="gateway-current"><div class="gateway-provider-icon">${icon('network')}</div><div><span>Active route</span><strong>${active.provider} · ${active.model}</strong><small>${active.available?'Available':'Local fallback active'}</small></div></div><div class="gateway-metrics"><div><span>Requests · 24h</span><strong>${stats.requests}</strong></div><div><span>Cache hits</span><strong>${stats.cache_hits}</strong></div><div><span>Average latency</span><strong>${stats.average_latency_ms}ms</strong></div><div><span>Rate limit</span><strong>${controls.rate_limit_per_minute}/min</strong></div></div><div class="provider-strip">${data.providers.map(p=>`<span class="${p.configured?'configured':''}"><i></i>${p.id}${p.free_tier?' · free':''}</span>`).join('')}</div><div class="gateway-guard">${icon('shield-check')} External models can explain analysis only. Order execution access: <b>disabled</b>.</div>`;if(window.lucide)lucide.createIcons();}

async function runAgent(e) {
  const btn=e.currentTarget; const old=btn.innerHTML; btn.disabled=true; btn.innerHTML=`${icon('loader-circle')} Scanning NSE…`; if(window.lucide) lucide.createIcons(); btn.querySelector('svg').style.animation='spin 1s linear infinite';
  try { const result=await api('/api/agent/run',{method:'POST'}); await refreshData(); render('dashboard'); showToast('Agent run complete',result.summary); }
  catch(err) { btn.disabled=false;btn.innerHTML=old;if(window.lucide)lucide.createIcons();showToast('Agent run failed',err.message); }
}
function showToast(title,message) { const t=document.getElementById('toast');t.querySelector('strong').textContent=title;t.querySelector('span').textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),4000); }
function toggleModal(open) { const m=document.getElementById('resetModal'); m.classList.toggle('open',open); m.setAttribute('aria-hidden',String(!open)); }
function toggleAuth(open) { const a=document.getElementById('authScreen'); a.classList.toggle('open',open); a.setAttribute('aria-hidden',String(!open)); document.body.style.overflow=open?'hidden':''; }

document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{render(b.dataset.view);document.getElementById('sidebar').classList.remove('open')}));
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('runAgentTop').addEventListener('click',runAgent);
document.getElementById('signOutBtn').addEventListener('click',()=>{authToken='';localStorage.removeItem('nivesh_token');if(marketTimer)clearInterval(marketTimer);toggleAuth(true)});
document.getElementById('authClose').addEventListener('click',()=>toggleAuth(false));
document.getElementById('authForm').addEventListener('submit',async e=>{e.preventDefault();const error=document.getElementById('authError');error.textContent='';const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;try{const body={email:document.getElementById('authEmail').value,password:document.getElementById('authPassword').value};if(creating)body.name=document.getElementById('authName').value;const result=await api(creating?'/api/auth/signup':'/api/auth/login',{method:'POST',body:JSON.stringify(body)});authToken=result.token;localStorage.setItem('nivesh_token',authToken);await refreshData();toggleAuth(false);render('dashboard');startMarketUpdater();}catch(err){error.textContent=err.message}finally{submit.disabled=false}});
let creating=false; document.getElementById('authToggle').addEventListener('click',e=>{creating=!creating;document.getElementById('signupName').hidden=!creating;document.getElementById('authEyebrow').textContent=creating?'Start paper trading':'Welcome back';document.getElementById('authTitle').textContent=creating?'Create your account':'Sign in to your desk';document.getElementById('authDesc').textContent=creating?'Build conviction without risking capital.':'Continue your paper-trading session.';e.currentTarget.textContent=creating?'Sign in instead':'Create an account';});
document.querySelectorAll('[data-close-modal]').forEach(b=>b.addEventListener('click',()=>toggleModal(false)));
document.getElementById('confirmReset').addEventListener('click',async()=>{try{await api('/api/portfolio/reset',{method:'POST'});await refreshData();toggleModal(false);render('settings');showToast('Paper portfolio reset','Starting balance restored to ₹10,00,000')}catch(err){showToast('Reset failed',err.message)}});
document.getElementById('resetModal').addEventListener('click',e=>{if(e.target===e.currentTarget)toggleModal(false)});
setInterval(()=>document.getElementById('clock').textContent=new Date().toLocaleTimeString('en-IN',{hour12:false,timeZone:'Asia/Kolkata'}),1000);
const style=document.createElement('style');style.textContent='@keyframes spin{to{transform:rotate(360deg)}}';document.head.appendChild(style);
async function initializeApp(){render('dashboard');if(!authToken){toggleAuth(true);return}try{await refreshData();render('dashboard');startMarketUpdater()}catch(err){authToken='';localStorage.removeItem('nivesh_token');toggleAuth(true)}}
initializeApp();
